import shutil
import openpyxl
from openpyxl.styles import PatternFill, Font

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title]

def norm_country(x):
    if x is None:
        return None
    s = str(x).strip().lower()
    return s if s else None

def to_number(x):
    if x is None:
        return 0.0
    if isinstance(x, bool):
        return 0.0
    if isinstance(x, (int, float)):
        return float(x)
    try:
        return float(str(x).strip())
    except Exception:
        return 0.0

lookup = {}
for r in range(4, 245):
    country = norm_country(vws.cell(row=r, column=5).value)
    if country is None:
        continue
    usd = to_number(vws.cell(row=r, column=6).value)
    if country not in lookup:
        lookup[country] = usd

fill = PatternFill(start_color="FFC7CE", end_color="FFC7CE", fill_type="solid")
font = Font(color="9C0006")

for r in range(4, 245):
    country = norm_country(vws.cell(row=r, column=5).value)
    value = lookup.get(country, 0.0)
    cell = ws.cell(row=r, column=6)
    cell.value = value
    cell.fill = fill
    cell.font = font

print("lookup size:", len(lookup))
print("F4:", ws["F4"].value)
print("F104:", ws["F104"].value)
print("F229:", ws["F229"].value)

wb.save(OUT)
